+  final i = filePath.lastIndexOf(_sessionPathSeparators);
+  return i < 0 ? null : filePath.substring(0, i);
+}
+
+String _sessionBaseName(String filePath) {
+  final i = filePath.lastIndexOf(_sessionPathSeparators);
+  return i < 0 ? filePath : filePath.substring(i + 1);
