      parseMs += phaseSw.elapsedMilliseconds;
      phaseSw
        ..reset()
        ..start();
      final load = await _collectSegmentRecords(
        fs,
        segmentPath,
        allLines,
        parsed,
        entries,
        seenRecordIds,
